export const DAY=86400000;
export const seedProfile={name:'Sahyadri Precision Works',district:'Pune',sector:'Engineering',investment:2.4,workers:42,effluent:true};
export function createNodes(p=seedProfile){
 const nodes=[{id:'entity',name:'Entity & site verification',short:'Entity verification',dept:'Industries',days:3,deps:[],docs:['Entity certificate'],reason:'Establish the applicant and proposed industrial site.',status:'approved',start:0,finished:3},{id:'plan',name:'Building plan review',short:'Building plan',dept:'Planning',days:12,deps:['entity'],docs:['Site plan'],reason:'The demo assumes a new industrial premises requiring plan review.',status:'in_progress',start:3}];
 if(p.effluent)nodes.push({id:'cte',name:'Consent to Establish',short:'Consent to Establish',dept:'Pollution control',days:15,deps:['entity'],docs:['Process note'],reason:'Selected because the intake declares process effluent. Real applicability needs verified rules.',status:'in_progress',start:3});
 nodes.push({id:'power',name:'Power feasibility review',short:'Power feasibility',dept:'Utilities',days:7,deps:['entity'],docs:['Load schedule'],reason:'The demonstration assumes a new industrial electricity connection.',status:'approved',start:3,finished:10},{id:'fire',name:'Fire safety review',short:'Fire safety',dept:'Fire services',days:10,deps:['plan'],docs:['Fire layout'],reason:'The demo models fire review after building plan approval.',status:'pending'});
 if(p.workers>=10)nodes.push({id:'factory',name:'Factory registration review',short:'Factory registration',dept:'Labour & safety',days:10,deps:['plan',...(p.effluent?['cte']:[])],docs:['Safety plan'],reason:'Illustrative rule: workforce of at least 10 selects this review. This is not a legal threshold determination.',status:'pending'});
 nodes.push({id:'ready',name:'Operational readiness',short:'Operational readiness',dept:'Orchestration',days:2,deps:['fire','power',...(p.workers>=10?['factory']:[])],docs:[],reason:'Internal milestone joining all selected branches, not a government licence.',status:'pending'});
 return nodes;
}
export function topology(nodes){const ids=new Set(nodes.map(n=>n.id));if(ids.size!==nodes.length)throw Error('Duplicate node identifiers');const ordered=[],seen=new Set();while(ordered.length<nodes.length){const ready=nodes.filter(n=>!seen.has(n.id)&&n.deps.every(d=>seen.has(d)));if(!ready.length)throw Error('Workflow contains a cycle or unknown dependency');for(const n of ready){ordered.push(n);seen.add(n.id);}}return ordered;}
export function schedule(nodes){const order=topology(nodes),times={};for(const n of order){const start=Math.max(0,...n.deps.map(d=>times[d].end));times[n.id]={start,end:start+n.days,level:n.deps.length?1+Math.max(...n.deps.map(d=>times[d].level)):0};}const total=Math.max(0,...Object.values(times).map(t=>t.end));const latest={};for(const n of [...order].reverse()){const children=nodes.filter(x=>x.deps.includes(n.id));const end=children.length?Math.min(...children.map(x=>latest[x.id].start)):total;latest[n.id]={start:end-n.days,end};}return {times,total,serial:nodes.reduce((s,n)=>s+n.days,0),critical:order.filter(n=>times[n.id].start===latest[n.id].start).map(n=>n.id)};}
export function status(n,nodes){return n.status==='pending'?(n.deps.every(d=>nodes.find(x=>x.id===d)?.status==='approved')?'ready':'blocked'):n.status;}
export function transition(nodes,id,action,day){const node=nodes.find(n=>n.id===id);if(!node)throw Error('Unknown approval');const current=status(node,nodes);if(action==='start'&&current==='ready'){node.status='in_progress';node.start=day;}else if(action==='approve'&&current==='in_progress'){node.status='approved';node.finished=day;}else throw Error('Invalid state transition or unmet prerequisites');return node;}
export function alerts(state){return state.nodes.filter(n=>n.status==='in_progress'&&state.day-n.start>n.days).map(n=>({title:n.name,detail:`${state.day-n.start-n.days} days beyond the illustrative ${n.days}-day SLA`,id:n.id}));}
export function expiryState(iso,now=new Date()){if(!iso)return {label:'No expiry recorded',tone:'neutral',days:null};const days=Math.ceil((new Date(iso+'T23:59:59')-now)/DAY);return {label:days<0?'Expired':days<=30?'Expires soon':'Within date',tone:days<0?'danger':days<=30?'warning':'success',days};}
